const settings = Object.fromEntries(
  $("Read settings").all().map((item) => [item.json.key, String(item.json.value ?? "")]),
);
const serviceName = Object.fromEntries(
  $("Read services").all().map((item) => [item.json.service_id, String(item.json.name ?? "")]),
);

const now = new Date();
const tomorrow = addDays(salonDate(now, settings.timezone), 1);
const remindedAt = salonStamp(now, settings.timezone);

const due = $input.all().map((item) => item.json).filter((booking) => {
  return String(booking.status ?? "").trim() === "confirmed"
    && String(booking.email_opt_out ?? "").trim() !== "yes"
    && String(booking.reminder_sent_at ?? "").trim() === ""
    && String(booking.date ?? "").trim() === tomorrow;
});

return due.map((booking) => {
  const name = serviceName[booking.service_id] || booking.service_id;
  const text = [
    `Reminder from ${settings.business_name}`,
    "",
    "Your appointment is tomorrow.",
    "",
    booking.customer_name,
    name,
    `${longDate(booking.date)}, ${booking.start_time}–${booking.end_time}`,
    "",
    settings.address,
    settings.phone,
    "",
    "To cancel or reschedule, reply to this email or call us.",
    "To stop these emails, reply STOP.",
  ].join("\n");

  return {
    json: {
      booking_id: booking.booking_id,
      to: String(booking.customer_email ?? "").trim(),
      subject: `Reminder: tomorrow at ${booking.start_time}, ${settings.business_name}`,
      text,
      reminder_sent_at: remindedAt,
    },
  };
});

function salonDate(instant, timeZone) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hourCycle: "h23",
  }).formatToParts(instant);
  const value = Object.fromEntries(parts.filter((part) => part.type !== "literal").map((part) => [part.type, part.value]));
  return `${value.year}-${value.month}-${value.day}`;
}

function addDays(date, days) {
  const [year, month, day] = date.split("-").map(Number);
  const shifted = new Date(Date.UTC(year, month - 1, day + days));
  const pad = (part) => String(part).padStart(2, "0");
  return `${shifted.getUTCFullYear()}-${pad(shifted.getUTCMonth() + 1)}-${pad(shifted.getUTCDate())}`;
}

function longDate(date) {
  const [year, month, day] = date.split("-").map(Number);
  return new Intl.DateTimeFormat("en-US", {
    weekday: "long",
    month: "long",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(year, month - 1, day)));
}

function salonStamp(instant, timeZone) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  }).formatToParts(instant);
  const value = Object.fromEntries(parts.filter((part) => part.type !== "literal").map((part) => [part.type, part.value]));
  const year = Number(value.year);
  const month = Number(value.month);
  const day = Number(value.day);
  const hour = Number(value.hour) % 24;
  const minute = Number(value.minute);
  const second = Number(value.second);
  const offsetMinutes = Math.round((Date.UTC(year, month - 1, day, hour, minute, second) - instant.getTime()) / 60000);
  const sign = offsetMinutes >= 0 ? "+" : "-";
  const absolute = Math.abs(offsetMinutes);
  const pad = (part) => String(part).padStart(2, "0");
  return `${year}-${pad(month)}-${pad(day)}T${pad(hour)}:${pad(minute)}:${pad(second)}${sign}${pad(Math.floor(absolute / 60))}:${pad(absolute % 60)}`;
}
